import { useIntl } from 'react-intl';

import { BigNumberSparkLineCard } from 'pages/components';

import { MAIN_CARDS_CONFIG } from '../../constants';
import type { ConnectionsCreativityMainCardsData } from '../../types';
import { StyledCardsGrid } from './PerformanceKpiSection.styles';

export interface PerformanceKpiSectionProps {
  mainCardsData: ConnectionsCreativityMainCardsData;
  loading?: boolean;
  error?: Error | null;
  onCardClick: () => void;
}

export const PerformanceKpiSection = ({
  mainCardsData,
  loading,
  error,
  onCardClick,
}: PerformanceKpiSectionProps) => {
  const { formatMessage } = useIntl();

  return (
    <StyledCardsGrid data-testid="cards-grid">
      {MAIN_CARDS_CONFIG.map(({ titleId, dataKey }) => (
        <BigNumberSparkLineCard
          key={titleId}
          containerTitle={formatMessage({ id: titleId })}
          loading={loading}
          error={error}
          data={mainCardsData[dataKey] ?? null}
          onClick={onCardClick}
        />
      ))}
    </StyledCardsGrid>
  );
};
